def band(score: int) -> str:
    if score >= 85:
        return "Strong"
    if score >= 70:
        return "Moderate"
    return "Attention Needed"

def skin_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Sensitivity / barrier weakness", "Glow imbalance"]
        services = ["Calming facial", "Barrier-repair serum plan"]
        warning = "Patch test advised before active treatments."
        homecare = "Use ceramide moisturizer, gentle cleanser, and SPF."
    elif score < 85:
        issues = ["Mild dehydration", "Uneven glow"]
        services = ["Hydration facial", "Brightening maintenance"]
        warning = "No critical warning."
        homecare = "Use SPF, hydration serum, and weekly mask."
    else:
        issues = ["Healthy skin baseline"]
        services = ["Glow maintenance facial", "Pre-event radiance ritual"]
        warning = "No critical warning."
        homecare = "Maintain hydration and sunscreen routine."
    return {"title":"Skin Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def hair_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Hair fall / breakage risk", "Scalp imbalance likely"]
        services = ["Scalp therapy", "Protein repair plan"]
        warning = "Trichology caution if shedding is persistent."
        homecare = "Use mild shampoo, scalp serum, and avoid heat stress."
    elif score < 85:
        issues = ["Dryness or dullness", "Mid-length care needed"]
        services = ["Protein spa", "Scalp balancing ritual"]
        warning = "No critical warning."
        homecare = "Use serum on lengths and heat protection."
    else:
        issues = ["Good strength and manageable scalp health"]
        services = ["Gloss spa", "Color-safe shine ritual"]
        warning = "No critical warning."
        homecare = "Maintain regular spa and color-safe cleansing."
    return {"title":"Hair Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def foot_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Heel crack risk", "Barrier dryness / pressure concern"]
        services = ["Repair pedicure", "Protective foot care plan"]
        warning = "Escalate if diabetic foot or pain symptoms are reported."
        homecare = "Use heel balm nightly and avoid harsh scrubs."
    elif score < 85:
        issues = ["Dry heel tendency", "Maintenance pedicure required"]
        services = ["Repair pedicure", "Heel softening therapy"]
        warning = "No critical warning."
        homecare = "Use regular hydration and closed-toe protection in dusty areas."
    else:
        issues = ["Healthy foot-care baseline"]
        services = ["Luxury pedicure", "Hydration maintenance"]
        warning = "No critical warning."
        homecare = "Maintain weekly hydration and hygiene routine."
    return {"title":"Foot Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def saree_bridal_plan(color: str, event_time: str) -> dict:
    c = (color or "").lower().strip()
    t = (event_time or "").lower().strip()
    if "maroon" in c:
        palette = "Deep maroon, antique gold, and muted rose highlights"
        jewelry = "Temple jewelry or antique kundan"
        hair = "Soft low bun with jasmine or textured bridal waves"
    elif "green" in c:
        palette = "Emerald glow with warm gold accents"
        jewelry = "Polki or emerald-finish jewelry"
        hair = "Braided bun with side volume"
    else:
        palette = "Classic bridal tones with gold and soft rose balance"
        jewelry = "Kundan / stone-work mix"
        hair = "Polished bridal bun or Hollywood waves"
    makeup = "Richer eye depth and long-wear matte base for evening lights." if ("evening" in t or "night" in t) else "Radiant base, fresh blush, and softer highlight for daylight photography."
    return {"palette":palette,"jewelry":jewelry,"hair":hair,"makeup":makeup,"looks":["Priority Look 1: Signature bridal glam","Priority Look 2: Soft luxe glow","Priority Look 3: Traditional regal finish"]}

def chatbot_reply(message: str, language: str = "en") -> dict:
    low = (message or "").strip().lower()
    if any(k in low for k in ["book","appointment","slot","calendar"]):
        expression="happy"; en="I can help with booking guidance. Tell me the service, date, and time, and I’ll suggest the best slot and prep notes."; ta="புக்கிங் உதவி செய்யலாம். சேவை, தேதி, நேரம் சொல்லுங்கள்; சரியான ஸ்லாட் மற்றும் தயாரிப்பு குறிப்புகளை சொல்கிறேன்."
    elif any(k in low for k in ["hair fall","dandruff","scalp","hair","color"]):
        expression="thoughtful"; en="For hair guidance, share the concern, recent treatments, and hair texture. I can suggest salon services and aftercare."; ta="முடி பிரச்சினைக்கு உங்கள் concern, recent treatments, hair texture சொன்னால் service மற்றும் aftercare சொல்கிறேன்."
    elif any(k in low for k in ["skin","facial","glow","acne","pigment"]):
        expression="thoughtful"; en="For skin guidance, tell me if the concern is acne, dullness, tanning, or sensitivity. I’ll suggest salon services and home-care."; ta="Skin guidance க்கு acne, dullness, tanning, sensitivity எது என்பதை சொல்லுங்கள். அதன்படி service மற்றும் home-care சொல்கிறேன்."
    elif any(k in low for k in ["foot","pedicure","heel","crack"]):
        expression="care"; en="For foot care, I’ll check dryness, heel cracks, and pressure discomfort. I can suggest pedicure therapy and caution notes."; ta="Foot care க்கு dryness, heel crack, pressure discomfort பார்க்கலாம். Pedicure therapy மற்றும் caution notes தருகிறேன்."
    elif any(k in low for k in ["bridal","saree","wedding","makeup"]):
        expression="happy"; en="For bridal planning, tell me the saree color, ceremony time, and whether you want classic, regal, or soft glam styling."; ta="Bridal plan க்கு saree color, function time, classic / regal / soft glam style எது வேண்டும் என்று சொல்லுங்கள்."
    else:
        expression="smile"; en="I’m your stylist assistant. Ask about hair, skin, bridal looks, booking support, or Tamil replies."; ta="நான் உங்கள் stylist assistant. Hair, skin, bridal looks, booking support அல்லது தமிழ் replies பற்றி கேளுங்கள்."
    return {"reply": ta if language == "ta" else en, "expression": expression}


