def derive_skin_tone_from_score(score: int) -> str:
    if score >= 85:
        return "Warm Radiant"
    if score >= 70:
        return "Neutral Golden"
    return "Deep / Sensitive Balance"

def beauty_passport_summary(skin_score: int, hair_score: int, foot_score: int, lifestyle: str = "Urban working routine") -> dict:
    tone = derive_skin_tone_from_score(skin_score)
    return {
        "passport_id": "BP-001",
        "skin_tone": tone,
        "skin_band": band(skin_score),
        "hair_band": band(hair_score),
        "foot_band": band(foot_score),
        "lifestyle": lifestyle,
        "recommended_journey": [
            "Consultation + profile update",
            "Targeted salon service plan",
            "Monthly beauty review",
            "Predictive home-care follow-up"
        ],
        "homecare_plan": [
            "AM cleanse + sunscreen",
            "Weekly scalp nourishment",
            "Hydration and barrier support",
            "Foot repair care twice weekly"
        ]
    }

def lehenga_recommendations(lehenga_color: str, skin_tone: str) -> dict:
    c = (lehenga_color or "").lower().strip()
    t = (skin_tone or "").lower().strip()
    if "maroon" in c or "wine" in c or "burgundy" in c:
        looks = [
            "Classic regal bridal glam with berry lips",
            "Soft gold eye bridal look with rose blush",
            "Temple-jewelry traditional bridal finish"
        ]
        jewelry = "Antique gold, kundan, temple jewelry, or ruby-toned stone set"
        makeup = "Gold-brown eyes, soft contour, warm highlighter, rose/berry lips"
    elif "green" in c:
        looks = [
            "Emerald royal bridal finish",
            "Soft glam with champagne eyes",
            "Traditional braid-and-jewelry bridal styling"
        ]
        jewelry = "Polki, emerald-finish stones, kundan choker and jhumka set"
        makeup = "Champagne shimmer eyes, peach-nude lips, soft bronzed cheeks"
    elif "pink" in c or "peach" in c:
        looks = [
            "Fresh romantic bridal glow",
            "Soft pink bridal luxe look",
            "Airbrushed pastel wedding finish"
        ]
        jewelry = "Rose gold, diamond-finish stones, pastel kundan"
        makeup = "Pink-rose blush, soft liner, glossy nude-pink lips"
    else:
        looks = [
            "Signature bridal glam",
            "Soft luxe wedding look",
            "Traditional polished bridal finish"
        ]
        jewelry = "Kundan, antique gold, layered bridal necklace set"
        makeup = "Balanced glam with warm eyes, soft contour, and bridal finish base"
    if "deep" in t:
        undertone_tip = "Choose richer berry, bronze, and antique-gold tones for contrast."
    elif "warm" in t:
        undertone_tip = "Choose gold, copper, peach, and warm rose accents."
    else:
        undertone_tip = "Choose balanced champagne, rose-gold, and neutral glam shades."
    return {
        "prelooks": looks,
        "jewelry": jewelry,
        "makeup": makeup,
        "undertone_tip": undertone_tip,
        "virtual_bridal_prompt": f"Elegant South Indian bridal preview wearing a {lehenga_color} lehenga with {jewelry}, {makeup}, realistic salon lighting, polished bridal photography"
    }

@app.get("/api/beauty-passport")
def api_beauty_passport(skin_score: int = 82, hair_score: int = 74, foot_score: int = 68, lifestyle: str = "Urban working routine"):
    return beauty_passport_summary(skin_score, hair_score, foot_score, lifestyle)

@app.get("/api/bridal-ml")
def api_bridal_ml(outfit_type: str = "saree", outfit_color: str = "maroon", skin_tone: str = "Warm Radiant"):
    outfit_type = (outfit_type or "saree").lower().strip()
    if outfit_type == "lehenga":
        return lehenga_recommendations(outfit_color, skin_tone)
    base = saree_bridal_plan(outfit_color, "evening")
    extra = lehenga_recommendations(outfit_color, skin_tone)
    return {
        "prelooks": base["looks"],
        "jewelry": base["jewelry"],
        "makeup": base["makeup"],
        "undertone_tip": extra["undertone_tip"],
        "virtual_bridal_prompt": f"Elegant South Indian bridal preview wearing a {outfit_color} saree with {base['jewelry']}, {base['makeup']}, realistic salon lighting, polished bridal photography"
    }



@app.get("/api/realtime-intelligence")
def api_realtime_intelligence():
    branches = BRANCH_PERFORMANCE
    avg_training = round(sum(x["training"] for x in branches)/len(branches), 1)
    avg_quality = round(sum(x["quality"] for x in branches)/len(branches), 1)
    avg_revenue = round(sum(x["revenue"] for x in branches)/len(branches), 1)
    weakest_gap = sorted(branches, key=lambda x: x["training"] + x["quality"] + x["revenue"])[0]
    insights = [
        "Convert training records, skill assessments, service audits, customer feedback, and revenue into one operating view.",
        "Higher training maturity aligns with stronger service quality and revenue performance in top branches.",
        f'Current highest-priority growth path: {weakest_gap["branch"]} needs {weakest_gap["skill_gap"]}.',
        "Use Beauty Passport and personalized service data to improve customer retention and long-term beauty journeys."
    ]
    recommendations = [
        "Strengthen L1 → L2 → L3 certification pathway using branch performance gaps.",
        "Link stylist skill assessments to service quality scorecards and revenue uplift tracking.",
        "Schedule proactive coaching for low-performing branches before customer feedback drops.",
        "Use bridal, skin, hair, and home-care journeys to build personalized beauty ecosystems."
    ]
    return {
        "avg_training": avg_training,
        "avg_quality": avg_quality,
        "avg_revenue": avg_revenue,
        "priority_branch": weakest_gap["branch"],
        "priority_gap": weakest_gap["skill_gap"],
        "insights": insights,
        "recommendations": recommendations,
        "eligible_users": [
            "Students",
            "AI developers",
            "Designers",
            "Beauty professionals",
            "Startups",
            "Data scientists",
            "Industry innovators"
        ]
    }

